// Fonction pour filtrer les liens YouTube et formater la réponse pour Telegram
const items = $input.all();
const results = [];

// Fonction pour valider qu'un lien pointe vers un produit spécifique
function isValidProductLink(link) {
  if (!link || typeof link !== 'string') return false;

  // Extraire le chemin de l'URL
  const pathMatch = link.match(/https?:\/\/[^\/]+(\/.*)?/);
  if (!pathMatch) return false;

  const path = pathMatch[1] || '/';

  // Le lien ne doit pas être juste la page d'accueil
  if (path === '/' || path === '') return false;

  // Compter les segments de chemin significatifs
  const segments = path.split('/').filter(p => p && p.length > 0);
  if (segments.length < 1) return false;

  // Vérifier qu'il y a un identifiant de produit (au moins 4 chiffres ou 8 caractères alphanum)
  const hasProductId = /\d{4,}|[a-zA-Z0-9]{8,}/.test(path);

  return hasProductId;
}

// Fonction pour valider qu'une image pointe vers une vraie image de produit
function isValidProductImage(imageUrl) {
  if (!imageUrl || typeof imageUrl !== 'string') return false;

  // Vérifier que c'est bien une URL d'image
  const imageExtensions = ['.jpg', '.jpeg', '.png', '.webp', '.gif', '.avif'];
  const hasImageExtension = imageExtensions.some(ext => imageUrl.toLowerCase().includes(ext));

  // Exclure les logos et images génériques
  const isGeneric = /logo|placeholder|default|generic|icon|brand/i.test(imageUrl);

  return hasImageExtension && !isGeneric;
}

for (const item of items) {
  try {
    const output = item.json.output || {};
    const category = output.category || 'general';
    const summary = output.summary || '';
    const resultsList = output.results || [];
    const comparisonTable = output.comparison_table || '';
    const recommendations = output.recommendations || '';

    // Filtrer les résultats pour exclure YouTube ET valider les liens/images
    const filteredResults = resultsList.filter(result => {
      const link = result.link || '';

      // Exclure YouTube
      if (link.includes('youtube.com') || link.includes('youtu.be')) {
        return false;
      }

      // Valider que le lien pointe vers un produit spécifique
      if (!isValidProductLink(link)) {
        console.log(`❌ Lien invalide (pas assez spécifique): ${link}`);
        return false;
      }

      // Valider l'image si présente
      if (result.image_url && !isValidProductImage(result.image_url)) {
        console.log(`⚠️ Image générique détectée: ${result.image_url}`);
        result.image_url = ''; // Supprimer l'image générique
      }

      return true;
    });

    // Construire le message formaté pour Telegram
    let message = `🔍 *Résultats de recherche - ${getCategoryEmoji(category)}*\n\n`;
    message += `📋 *Résumé :*\n${summary}\n\n`;

    if (filteredResults.length > 0) {
      message += `✨ *Options trouvées (${filteredResults.length}) :*\n\n`;

      filteredResults.forEach((result, index) => {
        message += `*${index + 1}. ${result.name || 'Sans nom'}*\n`;
        if (result.price) message += `💰 Prix : ${result.price}\n`;
        if (result.rating) message += `⭐ Note : ${result.rating}\n`;
        if (result.description) message += `📝 ${result.description}\n`;
        if (result.link) message += `🔗 [Voir le produit](${result.link})\n`;
        message += `\n`;
      });
    } else {
      message += `⚠️ Aucun résultat avec des liens directs trouvé.\n\nℹ️ L'agent n'a pas réussi à trouver de liens directs vers des produits spécifiques. Essayez de reformuler votre recherche.\n`;
    }

    if (comparisonTable) {
      message += `\n📊 *Tableau comparatif :*\n${comparisonTable}\n\n`;
    }

    if (recommendations) {
      message += `💡 *Recommandations :*\n${recommendations}\n`;
    }

    // Collecter les images VALIDÉES (première image de chaque résultat)
    const images = filteredResults
      .filter(r => r.image_url && isValidProductImage(r.image_url))
      .slice(0, 3) // Max 3 images
      .map(r => r.image_url);

    results.push({
      json: {
        chatId: item.json.message?.chat?.id || item.json.chatId,
        message: message,
        images: images,
        category: category,
        resultsCount: filteredResults.length,
        rawResults: filteredResults // Résultats filtrés et validés
      }
    });

  } catch (error) {
    results.push({
      json: {
        chatId: item.json.message?.chat?.id || item.json.chatId,
        message: `❌ Erreur lors du formatage de la réponse : ${error.message}\n\n🔍 Debug: ${JSON.stringify(error, null, 2)}`,
        images: [],
        category: 'error',
        resultsCount: 0,
        rawResults: []
      }
    });
  }
}

function getCategoryEmoji(category) {
  const emojis = {
    'hotel': '🏨 Hôtels',
    'flight': '✈️ Vols',
    'apartment': '🏢 Appart-hôtels',
    'restaurant': '🍽️ Restaurants',
    'leisure': '🎢 Loisirs',
    'tech_product': '💻 High-Tech',
    'general_product': '🛍️ Shopping',
    'general': '🔎 Recherche'
  };
  return emojis[category] || '🔎 Recherche';
}

return results;

